"""Tests for shapes.units."""

import pytest

from shapes import units


def test_convert_km_to_m() -> None:
    assert units.convert(1, "km", "m") == pytest.approx(1000.0)


def test_convert_unknown_unit_raises() -> None:
    with pytest.raises(KeyError):
        units.convert(1, "m", "parsec")


def test_temperature_round_trip() -> None:
    assert units.fahrenheit_to_celsius(units.celsius_to_fahrenheit(37.0)) == pytest.approx(37.0)
